-- ============================================================
-- 040_tech_spec_leads.sql
-- Contacts generated by a fiche technique for its importer:
--   1) quote_requests — « Demande de devis » form (name, phone, email,
--      consent), emailed to the importer from devis@moto-scoot.tn
--   2) lead_events    — one row per tap on Appel, WhatsApp, Comparer and
--      per quote sent: the counters shown to the importer in the admin
-- The controller (techSpecLeadsController.js) also creates both tables
-- at first use (same idea as ensureVisitTables), so the feature works
-- even if this file has not been run on the server yet.
-- ============================================================

CREATE TABLE IF NOT EXISTS quote_requests (
  id            BIGSERIAL PRIMARY KEY,
  tech_spec_id  UUID REFERENCES tech_specs(id) ON DELETE SET NULL,
  importer_id   UUID REFERENCES importers(id) ON DELETE SET NULL,
  brand         VARCHAR(100),
  model         VARCHAR(150),
  first_name    VARCHAR(80)  NOT NULL,
  last_name     VARCHAR(80)  NOT NULL,
  phone         VARCHAR(40)  NOT NULL,
  email         VARCHAR(160) NOT NULL,
  consent       BOOLEAN      NOT NULL DEFAULT FALSE,
  page_url      TEXT,
  ip_address    VARCHAR(64),
  created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_quote_requests_importer ON quote_requests (importer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_quote_requests_created ON quote_requests (created_at DESC);

CREATE TABLE IF NOT EXISTS lead_events (
  id            BIGSERIAL PRIMARY KEY,
  tech_spec_id  UUID REFERENCES tech_specs(id) ON DELETE SET NULL,
  importer_id   UUID REFERENCES importers(id) ON DELETE SET NULL,
  kind          VARCHAR(16) NOT NULL CHECK (kind IN ('call', 'whatsapp', 'quote', 'compare')),
  session_id    VARCHAR(64),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_lead_events_importer ON lead_events (importer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_lead_events_spec ON lead_events (tech_spec_id, created_at DESC);
